package controller;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.IOException;import java.util.*;import service.ChuyenGiaoService;import util.XuLyJson;
/** GET /api/delivery-trips, /orders, /{id}; POST / {driverId,vehicleId,expectedAt,orderIds theo thứ tự}; /resources {type,name,phone|plate}; /{id}/start. */
@WebServlet("/api/delivery-trips/*") public class ChuyenGiaoServlet extends NghiepVuKhoServlet{private final ChuyenGiaoService s=new ChuyenGiaoService();protected void doGet(HttpServletRequest q,HttpServletResponse r)throws IOException{try{String p=path(q);send(r,p.equals("/")?s.list(user(q),roles(q)):p.equals("/orders")?s.orders(user(q),roles(q)):s.detail(id(p.substring(1)),user(q),roles(q)));}catch(Exception e){fail(r,e);}}protected void doPost(HttpServletRequest q,HttpServletResponse r)throws IOException{try{String p=path(q);if(p.equals("/"))created(r,XuLyJson.stringify(s.detail(s.create(user(q),roles(q),XuLyJson.object(body(q))),user(q),roles(q))));else if(p.equals("/resources"))created(r,XuLyJson.stringify(Map.of("id",s.resource(user(q),roles(q),XuLyJson.object(body(q))))));else if(p.matches("/\\d+/start")){s.start(id(p.split("/")[1]),user(q),roles(q));send(r,Map.of("message","Đã khởi hành"));}else throw new NoSuchElementException("Không tìm thấy chức năng");}catch(Exception e){fail(r,e);}}}
